#define ID "144c654344aa716d6f3abcc1ca90e5641e4e2a7f633bc09fe3baf64585819a49"
#define OTHER "6020c4717a928d9326bc984403219d94a206339d28359551a87316ea2873358c"

static void test_hex(void)
{
	u8 *a = channel_asset_from_hex(tmpctx, ID, strlen(ID));

	/* 0x01 (explicit), then the id byte-reversed, as in the wire. */
	assert(tal_bytelen(a) == ELEMENTS_ASSET_LEN);
	assert(a[0] == 0x01);
	assert(a[1] == 0x49 && a[2] == 0x9a && a[32] == 0x14);

	/* Printing gives the same string back. */
	assert(streq(fmt_channel_asset(tmpctx, a), ID));

	/* Not an asset id: too short, too long, not hex. */
	assert(!channel_asset_from_hex(tmpctx, "", 0));
	assert(!channel_asset_from_hex(tmpctx, ID, strlen(ID) - 2));
	assert(!channel_asset_from_hex(tmpctx, ID "00", strlen(ID) + 2));
	assert(!channel_asset_from_hex(tmpctx,
				      "zz4c654344aa716d6f3abcc1ca90e5641e4e2a7f633bc09fe3baf64585819a49",
				      strlen(ID)));
}

static void test_eq(void)
{
	u8 *a = channel_asset_from_hex(tmpctx, ID, strlen(ID));
	u8 *c = channel_asset_from_hex(tmpctx, OTHER, strlen(OTHER));
	struct channel_asset *x = channel_asset_new(tmpctx, a, AMOUNT_SAT(1));
	struct channel_asset *y = channel_asset_new(tmpctx, a, AMOUNT_SAT(2));
	struct channel_asset *z = channel_asset_new(tmpctx, c, AMOUNT_SAT(1));

	/* NULL is L-BTC; the fee reserve isn't part of the identity. */
	assert(channel_asset_eq(NULL, NULL));
	assert(!channel_asset_eq(x, NULL));
	assert(!channel_asset_eq(NULL, x));
	assert(channel_asset_eq(x, x));
	assert(channel_asset_eq(x, y));
	assert(!channel_asset_eq(x, z));
	assert(channel_asset_tag(NULL) == NULL);
	assert(channel_asset_tag(x) == x->tag);
}

static void test_wire(void)
{
	u8 *a = channel_asset_from_hex(tmpctx, ID, strlen(ID));
	struct channel_asset *x = channel_asset_new(tmpctx, a, AMOUNT_SAT(12345));
	struct channel_asset y;
	u8 *wire = tal_arr(tmpctx, u8, 0);
	const u8 *cursor;
	size_t max;

	towire_channel_asset(&wire, x);
	assert(tal_bytelen(wire) == ELEMENTS_ASSET_LEN + 8);
	cursor = wire;
	max = tal_bytelen(wire);
	fromwire_channel_asset(&cursor, &max, &y);
	assert(max == 0);
	assert(channel_asset_eq(&y, x));
	assert(y.fee_reserve.satoshis == 12345); /* Raw: test */
}

static void test_fee_reserve_outpoint(void)
{
	struct bitcoin_outpoint funding, reserve;

	/* The fee reserve is the output after the funding output. */
	memset(&funding, 7, sizeof(funding));
	funding.n = 0;
	reserve = fee_reserve_outpoint(&funding);
	assert(reserve.n == 1);
	assert(memcmp(&reserve.txid, &funding.txid, sizeof(funding.txid)) == 0);
	funding.n = 41;
	assert(fee_reserve_outpoint(&funding).n == 42);
}

static void test_explicit(void)
{
	struct wally_tx_output out;
	u8 asset[ELEMENTS_ASSET_LEN], value[9];

	memset(asset, 0, sizeof(asset));
	memset(value, 0, sizeof(value));
	asset[0] = 0x01;
	value[0] = 0x01;
	memset(&out, 0, sizeof(out));
	out.asset = asset;
	out.asset_len = sizeof(asset);
	out.value = value;
	out.value_len = sizeof(value);
	assert(elements_output_is_explicit(&out));

	/* A blinded asset commitment starts with 0x0a or 0x0b. */
	asset[0] = 0x0a;
	assert(!elements_output_is_explicit(&out));
	asset[0] = 0x01;

	/* A blinded value is 33 bytes. */
	out.value_len = 33;
	value[0] = 0x08;
	assert(!elements_output_is_explicit(&out));
	out.value_len = 9;
	value[0] = 0x01;
	assert(elements_output_is_explicit(&out));

	/* Off Liquid there is nothing to blind. */
	chainparams = chainparams_for_network("regtest");
	asset[0] = 0x0a;
	assert(elements_output_is_explicit(&out));
	chainparams = chainparams_for_network("liquid-regtest");
}

/* An explicit asset with a confidential value is as unknown as a blinded
 * output: its value commitment is never read as an amount, and its tag
 * never matches L-BTC (or a channel asset). */
static void test_confidential_value_amount(void)
{
	struct wally_tx_output out;
	struct amount_asset amt;
	u8 asset[ELEMENTS_ASSET_LEN], value[33];

	memcpy(asset, chainparams->fee_asset_tag, sizeof(asset));
	memset(value, 0xff, sizeof(value));
	memset(&out, 0, sizeof(out));
	out.asset = asset;
	out.asset_len = sizeof(asset);
	out.value = value;

	/* Explicit: 0x01 and 8 bytes big-endian. */
	value[0] = 0x01;
	memset(value + 1, 0, 8);
	value[8] = 0xe8;
	value[7] = 0x03;
	out.value_len = 9;
	amt = wally_tx_output_get_amount(&out);
	assert(amount_asset_is_main(&amt));
	assert(amt.value == 1000);

	/* Confidential: a 33-byte commitment, whatever its bytes say. */
	memset(value, 0xff, sizeof(value));
	value[0] = 0x08;
	out.value_len = 33;
	amt = wally_tx_output_get_amount(&out);
	assert(!amount_asset_is_main(&amt));
	assert(amt.value == 0);
	assert(!channel_asset_tag_eq(amt.asset, chainparams->fee_asset_tag));
}

static void test_tag_valid(void)
{
	u8 tag[ELEMENTS_ASSET_LEN];

	memset(tag, 0x42, sizeof(tag));
	tag[0] = 0x01;
	assert(channel_asset_tag_valid(tag, sizeof(tag)));
	/* Wrong length. */
	assert(!channel_asset_tag_valid(tag, sizeof(tag) - 1));
	/* Not explicit (a blinded asset commitment's prefix). */
	tag[0] = 0x0a;
	assert(!channel_asset_tag_valid(tag, sizeof(tag)));
	/* The fee asset is an ordinary channel's, not an asset channel's. */
	assert(!channel_asset_tag_valid(chainparams->fee_asset_tag,
					ELEMENTS_ASSET_LEN));
}

static void test_finish_tx(void)
{
	const u8 *tag = channel_asset_from_hex(tmpctx, ID, strlen(ID));
	const struct channel_asset *asset
		= channel_asset_new(tmpctx, tag, AMOUNT_SAT(2000));
	/* Any script will do: a P2WPKH shape. */
	u8 *script = tal_arrz(tmpctx, u8, 22);
	struct bitcoin_tx *tx;
	struct amount_asset amt;

	script[1] = 0x14;

	/* A 100000-unit channel: 60000 to the opener (output 0), 39000 to
	 * the other side (1), an anchor in the chain's coin (2), and 1000
	 * units of trimmed HTLCs unpaid. */
	tx = bitcoin_tx(tmpctx, chainparams, 2, 4, 0);
	bitcoin_tx_add_asset_output(tx, script, NULL, AMOUNT_SAT(60000), tag);
	bitcoin_tx_add_asset_output(tx, script, NULL, AMOUNT_SAT(39000), tag);
	bitcoin_tx_add_output(tx, script, NULL, AMOUNT_SAT(330));

	/* The leftovers go to the opener's output. */
	channel_asset_finish_tx(tx, asset, AMOUNT_SAT(100000), 0, 1);
	amt = bitcoin_tx_output_get_amount(tx, 0);
	assert(memeq(amt.asset, ELEMENTS_ASSET_LEN, tag, ELEMENTS_ASSET_LEN) && amt.value == 61000);
	amt = bitcoin_tx_output_get_amount(tx, 1);
	assert(memeq(amt.asset, ELEMENTS_ASSET_LEN, tag, ELEMENTS_ASSET_LEN) && amt.value == 39000);
	amt = bitcoin_tx_output_get_amount(tx, 2);
	assert(amount_asset_is_main(&amt) && amt.value == 330);

	/* Without an opener output, to the other side's. */
	channel_asset_finish_tx(tx, asset, AMOUNT_SAT(100500), -1, 1);
	amt = bitcoin_tx_output_get_amount(tx, 1);
	assert(amt.value == 39500);

	/* Nothing left over: nothing changes. */
	channel_asset_finish_tx(tx, asset, AMOUNT_SAT(100500), 0, 1);
	amt = bitcoin_tx_output_get_amount(tx, 0);
	assert(amt.value == 61000);
	amt = bitcoin_tx_output_get_amount(tx, 1);
	assert(amt.value == 39500);

	/* Trimmed HTLCs are burned, not paid to anyone: 900 units of them to
	 * an OP_RETURN, and only the 100 left (rounding) to the opener. */
	tx = bitcoin_tx(tmpctx, chainparams, 2, 4, 0);
	bitcoin_tx_add_asset_output(tx, script, NULL, AMOUNT_SAT(60000), tag);
	bitcoin_tx_add_asset_output(tx, script, NULL, AMOUNT_SAT(39000), tag);
	assert(channel_asset_add_burn(tx, asset, AMOUNT_SAT(0)) == -1);
	assert(channel_asset_add_burn(tx, asset, AMOUNT_SAT(900)) == 2);
	assert(channel_asset_is_burn(&tx->wtx->outputs[2]));
	assert(!channel_asset_is_burn(&tx->wtx->outputs[0]));
	amt = bitcoin_tx_output_get_amount(tx, 2);
	assert(memeq(amt.asset, ELEMENTS_ASSET_LEN, tag, ELEMENTS_ASSET_LEN) && amt.value == 900);
	channel_asset_finish_tx(tx, asset, AMOUNT_SAT(100000), 0, 1);
	amt = bitcoin_tx_output_get_amount(tx, 0);
	assert(amt.value == 60100);
	amt = bitcoin_tx_output_get_amount(tx, 1);
	assert(amt.value == 39000);

	/* The fee reserve sits right after the funding output. */
	{
		struct bitcoin_outpoint funding, reserve;
		memset(&funding, 0, sizeof(funding));
		funding.n = 3;
		reserve = fee_reserve_outpoint(&funding);
		assert(reserve.n == 4);
		assert(bitcoin_txid_eq(&reserve.txid, &funding.txid));
	}
}

int main(int argc, char *argv[])
{
	common_setup(argv[0]);
	chainparams = chainparams_for_network("liquid-regtest");

	test_hex();
	test_eq();
	test_wire();
	test_fee_reserve_outpoint();
	test_explicit();
	test_confidential_value_amount();
	test_tag_valid();
	test_finish_tx();

	common_shutdown();
	return 0;
}
